values (
  'en-science-basics-trivia',
  'Science Trivia: Planets, Elements and the Human Body',
  'Eight questions on facts every curious mind knows: the planets, chemical elements and the human body.',
  'trivia',
  'easy',
  'en',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"How many planets orbit the Sun in our solar system?","options":[{"id":"a","text":"7","is_correct":false},{"id":"b","text":"8","is_correct":true},{"id":"c","text":"9","is_correct":false},{"id":"d","text":"10","is_correct":false}],"explanation":"Pluto was reclassified as a dwarf planet in 2006, leaving eight planets."},{"id":"q2","question":"Which planet is closest to the Sun?","options":[{"id":"a","text":"Venus","is_correct":false},{"id":"b","text":"Earth","is_correct":false},{"id":"c","text":"Mercury","is_correct":true},{"id":"d","text":"Mars","is_correct":false}],"explanation":"Mercury completes an orbit in about 88 days."},{"id":"q3","question":"What is the chemical formula of water?","options":[{"id":"a","text":"CO2","is_correct":false},{"id":"b","text":"H2O","is_correct":true},{"id":"c","text":"O2","is_correct":false},{"id":"d","text":"NaCl","is_correct":false}],"explanation":"Each water molecule has two hydrogen atoms and one oxygen atom."},{"id":"q4","question":"Which gas do plants absorb from the air for photosynthesis?","options":[{"id":"a","text":"Oxygen","is_correct":false},{"id":"b","text":"Nitrogen","is_correct":false},{"id":"c","text":"Hydrogen","is_correct":false},{"id":"d","text":"Carbon dioxide","is_correct":true}],"explanation":"Plants take in carbon dioxide and release oxygen during photosynthesis."},{"id":"q5","question":"What is the largest organ of the human body?","options":[{"id":"a","text":"The liver","is_correct":false},{"id":"b","text":"The skin","is_correct":true},{"id":"c","text":"The heart","is_correct":false},{"id":"d","text":"The lungs","is_correct":false}],"explanation":"The skin is the largest organ, covering the whole body."},{"id":"q6","question":"Which planet is known as the Red Planet?","options":[{"id":"a","text":"Jupiter","is_correct":false},{"id":"b","text":"Venus","is_correct":false},{"id":"c","text":"Saturn","is_correct":false},{"id":"d","text":"Mars","is_correct":true}],"explanation":"Iron oxide dust gives Mars its reddish colour."},{"id":"q7","question":"Which force keeps the planets in orbit around the Sun?","options":[{"id":"a","text":"Magnetism","is_correct":false},{"id":"b","text":"Gravity","is_correct":true},{"id":"c","text":"Friction","is_correct":false},{"id":"d","text":"Electricity","is_correct":false}],"explanation":"The Sun''s gravity pulls the planets into their orbits."},{"id":"q8","question":"How many bones does an adult human skeleton normally have?","options":[{"id":"a","text":"106","is_correct":false},{"id":"b","text":"206","is_correct":true},{"id":"c","text":"306","is_correct":false},{"id":"d","text":"406","is_correct":false}],"explanation":"Babies are born with about 300 bones that fuse into 206 by adulthood."}]'::jsonb,
  null,
  array['science', 'trivia', 'space', 'human body']::text[],
  3,
  'published',
  false,
  false,
  now()
)
