values (
  'es-trivia-ciencia-basica',
  'Trivia de ciencia: planetas, elementos y el cuerpo humano',
  'Ocho preguntas sobre hechos que toda mente curiosa conoce: los planetas, los elementos químicos y el cuerpo humano.',
  'trivia',
  'easy',
  'es',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"¿Cuántos planetas orbitan el Sol en nuestro sistema solar?","options":[{"id":"a","text":"7","is_correct":false},{"id":"b","text":"8","is_correct":true},{"id":"c","text":"9","is_correct":false},{"id":"d","text":"10","is_correct":false}],"explanation":"Plutón fue reclasificado como planeta enano en 2006, quedando ocho planetas."},{"id":"q2","question":"¿Qué planeta está más cerca del Sol?","options":[{"id":"a","text":"Venus","is_correct":false},{"id":"b","text":"La Tierra","is_correct":false},{"id":"c","text":"Mercurio","is_correct":true},{"id":"d","text":"Marte","is_correct":false}],"explanation":"Mercurio completa una órbita en unos 88 días."},{"id":"q3","question":"¿Cuál es la fórmula química del agua?","options":[{"id":"a","text":"CO2","is_correct":false},{"id":"b","text":"H2O","is_correct":true},{"id":"c","text":"O2","is_correct":false},{"id":"d","text":"NaCl","is_correct":false}],"explanation":"Cada molécula de agua tiene dos átomos de hidrógeno y uno de oxígeno."},{"id":"q4","question":"¿Qué gas absorben las plantas del aire para la fotosíntesis?","options":[{"id":"a","text":"Oxígeno","is_correct":false},{"id":"b","text":"Nitrógeno","is_correct":false},{"id":"c","text":"Hidrógeno","is_correct":false},{"id":"d","text":"Dióxido de carbono","is_correct":true}],"explanation":"Las plantas toman dióxido de carbono y liberan oxígeno durante la fotosíntesis."},{"id":"q5","question":"¿Cuál es el órgano más grande del cuerpo humano?","options":[{"id":"a","text":"El hígado","is_correct":false},{"id":"b","text":"La piel","is_correct":true},{"id":"c","text":"El corazón","is_correct":false},{"id":"d","text":"Los pulmones","is_correct":false}],"explanation":"La piel es el órgano más grande, pues cubre todo el cuerpo."},{"id":"q6","question":"¿Qué planeta es conocido como el planeta rojo?","options":[{"id":"a","text":"Júpiter","is_correct":false},{"id":"b","text":"Venus","is_correct":false},{"id":"c","text":"Saturno","is_correct":false},{"id":"d","text":"Marte","is_correct":true}],"explanation":"El polvo rico en óxido de hierro le da a Marte su color rojizo."},{"id":"q7","question":"¿Qué fuerza mantiene a los planetas en órbita alrededor del Sol?","options":[{"id":"a","text":"El magnetismo","is_correct":false},{"id":"b","text":"La gravedad","is_correct":true},{"id":"c","text":"La fricción","is_correct":false},{"id":"d","text":"La electricidad","is_correct":false}],"explanation":"La gravedad del Sol mantiene a los planetas en sus órbitas."},{"id":"q8","question":"¿Cuántos huesos tiene normalmente el esqueleto de un adulto?","options":[{"id":"a","text":"106","is_correct":false},{"id":"b","text":"206","is_correct":true},{"id":"c","text":"306","is_correct":false},{"id":"d","text":"406","is_correct":false}],"explanation":"Los bebés nacen con unos 300 huesos que se fusionan hasta quedar en 206."}]'::jsonb,
  null,
  array['ciencia', 'trivia', 'espacio', 'cuerpo humano']::text[],
  3,
  'published',
  false,
  false,
  now()
)
