insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-computing-history-trivia',
  'Technology Trivia: Milestones of Computing and the Web',
  'From ENIAC to the World Wide Web: eight questions on the milestones that built modern computing.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'technology'),
  '[{"id":"q1","question":"What does the abbreviation WWW stand for?","options":[{"id":"a","text":"World Wide Web","is_correct":true},{"id":"b","text":"Wide World Web","is_correct":false},{"id":"c","text":"World Web Window","is_correct":false},{"id":"d","text":"Web World Wide","is_correct":false}],"explanation":"Tim Berners-Lee named his 1989 proposal the World Wide Web."},{"id":"q2","question":"Who proposed the World Wide Web while working at CERN in 1989?","options":[{"id":"a","text":"Bill Gates","is_correct":false},{"id":"b","text":"Steve Jobs","is_correct":false},{"id":"c","text":"Tim Berners-Lee","is_correct":true},{"id":"d","text":"Linus Torvalds","is_correct":false}],"explanation":"Berners-Lee wrote the proposal and later built the first browser and server."},{"id":"q3","question":"Which 1940s machine is widely regarded as the first general-purpose electronic computer?","options":[{"id":"a","text":"UNIVAC","is_correct":false},{"id":"b","text":"ENIAC","is_correct":true},{"id":"c","text":"Colossus","is_correct":false},{"id":"d","text":"Harvard Mark I","is_correct":false}],"explanation":"ENIAC, completed in 1945, could be reprogrammed for different problems."},{"id":"q4","question":"What does HTTP stand for?","options":[{"id":"a","text":"HyperText Transfer Protocol","is_correct":true},{"id":"b","text":"HyperText Transmission Process","is_correct":false},{"id":"c","text":"High Transfer Text Protocol","is_correct":false},{"id":"d","text":"Host Terminal Text Protocol","is_correct":false}],"explanation":"HTTP is the protocol browsers use to fetch web pages."},{"id":"q5","question":"In which decade did ARPANET, the forerunner of the internet, first connect computers?","options":[{"id":"a","text":"1950s","is_correct":false},{"id":"b","text":"1960s","is_correct":true},{"id":"c","text":"1970s","is_correct":false},{"id":"d","text":"1980s","is_correct":false}],"explanation":"The first ARPANET link went live in 1969 between UCLA and Stanford."},{"id":"q6","question":"Who is credited with sending the first networked email using the @ symbol in 1971?","options":[{"id":"a","text":"Vint Cerf","is_correct":false},{"id":"b","text":"Alan Turing","is_correct":false},{"id":"c","text":"Ray Tomlinson","is_correct":true},{"id":"d","text":"Tim Berners-Lee","is_correct":false}],"explanation":"Tomlinson chose @ to separate the user''s name from the machine''s."},{"id":"q7","question":"Whose 1936 paper described a theoretical machine that became the basis of computer science?","options":[{"id":"a","text":"Alan Turing","is_correct":true},{"id":"b","text":"John von Neumann","is_correct":false},{"id":"c","text":"Charles Babbage","is_correct":false},{"id":"d","text":"Ada Lovelace","is_correct":false}],"explanation":"The Turing machine formalised the idea of computation itself."},{"id":"q8","question":"In which year was the first iPhone released?","options":[{"id":"a","text":"2005","is_correct":false},{"id":"b","text":"2007","is_correct":true},{"id":"c","text":"2009","is_correct":false},{"id":"d","text":"2010","is_correct":false}],"explanation":"Apple announced the iPhone in January 2007 and shipped it that June."}]'::jsonb,
  null,
  array['technology', 'trivia', 'computing', 'internet history']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-historia-computacion',
  'Trivia de tecnología: hitos de la informática y la web',
  'De la ENIAC a la World Wide Web: ocho preguntas sobre los hitos que crearon la informática moderna.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'technology'),
  '[{"id":"q1","question":"¿Qué significa la sigla WWW?","options":[{"id":"a","text":"World Wide Web","is_correct":true},{"id":"b","text":"Wide World Web","is_correct":false},{"id":"c","text":"World Web Window","is_correct":false},{"id":"d","text":"Web World Wide","is_correct":false}],"explanation":"Tim Berners-Lee llamó World Wide Web a su propuesta de 1989."},{"id":"q2","question":"¿Quién propuso la World Wide Web mientras trabajaba en el CERN en 1989?","options":[{"id":"a","text":"Bill Gates","is_correct":false},{"id":"b","text":"Steve Jobs","is_correct":false},{"id":"c","text":"Tim Berners-Lee","is_correct":true},{"id":"d","text":"Linus Torvalds","is_correct":false}],"explanation":"Berners-Lee escribió la propuesta y luego creó el primer navegador y servidor."},{"id":"q3","question":"¿Qué máquina de los años 40 se considera la primera computadora electrónica de propósito general?","options":[{"id":"a","text":"UNIVAC","is_correct":false},{"id":"b","text":"ENIAC","is_correct":true},{"id":"c","text":"Colossus","is_correct":false},{"id":"d","text":"Harvard Mark I","is_correct":false}],"explanation":"ENIAC, terminada en 1945, podía reprogramarse para distintos problemas."},{"id":"q4","question":"¿Qué significa HTTP?","options":[{"id":"a","text":"HyperText Transfer Protocol","is_correct":true},{"id":"b","text":"HyperText Transmission Process","is_correct":false},{"id":"c","text":"High Transfer Text Protocol","is_correct":false},{"id":"d","text":"Host Terminal Text Protocol","is_correct":false}],"explanation":"HTTP es el protocolo que usan los navegadores para cargar páginas web."},{"id":"q5","question":"¿En qué década conectó ARPANET, precursora de internet, sus primeras computadoras?","options":[{"id":"a","text":"Los años 50","is_correct":false},{"id":"b","text":"Los años 60","is_correct":true},{"id":"c","text":"Los años 70","is_correct":false},{"id":"d","text":"Los años 80","is_correct":false}],"explanation":"El primer enlace de ARPANET funcionó en 1969 entre UCLA y Stanford."},{"id":"q6","question":"¿Quién envió en 1971 el primer correo electrónico en red usando el símbolo @?","options":[{"id":"a","text":"Vint Cerf","is_correct":false},{"id":"b","text":"Alan Turing","is_correct":false},{"id":"c","text":"Ray Tomlinson","is_correct":true},{"id":"d","text":"Tim Berners-Lee","is_correct":false}],"explanation":"Tomlinson eligió @ para separar el nombre del usuario del de la máquina."},{"id":"q7","question":"¿Quién describió en 1936 una máquina teórica que sentó las bases de la informática?","options":[{"id":"a","text":"Alan Turing","is_correct":true},{"id":"b","text":"John von Neumann","is_correct":false},{"id":"c","text":"Charles Babbage","is_correct":false},{"id":"d","text":"Ada Lovelace","is_correct":false}],"explanation":"La máquina de Turing formalizó la idea misma de computación."},{"id":"q8","question":"¿En qué año se lanzó el primer iPhone?","options":[{"id":"a","text":"2005","is_correct":false},{"id":"b","text":"2007","is_correct":true},{"id":"c","text":"2009","is_correct":false},{"id":"d","text":"2010","is_correct":false}],"explanation":"Apple anunció el iPhone en enero de 2007 y lo vendió desde junio de ese año."}]'::jsonb,
  null,
  array['tecnología', 'trivia', 'informática', 'historia de internet']::text[],
  3,
  'published',
  false,
  false,
  now()
)
