insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-food-origins-trivia',
  'Food Trivia: Where Dishes and Ingredients Come From',
  'Pizza, coffee, tea and chocolate: eight questions on where famous dishes and ingredients come from.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'food-drink'),
  '[{"id":"q1","question":"Which country is the birthplace of pizza?","options":[{"id":"a","text":"France","is_correct":false},{"id":"b","text":"Italy","is_correct":true},{"id":"c","text":"Greece","is_correct":false},{"id":"d","text":"Spain","is_correct":false}],"explanation":"Modern pizza was born in Naples in the 18th and 19th centuries."},{"id":"q2","question":"The croissant was inspired by the kipferl, a pastry from which city?","options":[{"id":"a","text":"Paris","is_correct":false},{"id":"b","text":"Brussels","is_correct":false},{"id":"c","text":"Vienna","is_correct":true},{"id":"d","text":"Berlin","is_correct":false}],"explanation":"The Viennese kipferl travelled to France and became the croissant."},{"id":"q3","question":"Where was tea first cultivated and drunk?","options":[{"id":"a","text":"India","is_correct":false},{"id":"b","text":"Japan","is_correct":false},{"id":"c","text":"Sri Lanka","is_correct":false},{"id":"d","text":"China","is_correct":true}],"explanation":"Tea drinking began in China thousands of years ago."},{"id":"q4","question":"According to tradition, coffee has its origins in which African country?","options":[{"id":"a","text":"Ethiopia","is_correct":true},{"id":"b","text":"Kenya","is_correct":false},{"id":"c","text":"Morocco","is_correct":false},{"id":"d","text":"Egypt","is_correct":false}],"explanation":"The coffee plant is native to Ethiopia, where the drink''s story begins."},{"id":"q5","question":"Sushi in its modern form comes from which country?","options":[{"id":"a","text":"China","is_correct":false},{"id":"b","text":"Korea","is_correct":false},{"id":"c","text":"Japan","is_correct":true},{"id":"d","text":"Thailand","is_correct":false}],"explanation":"Nigiri-style sushi emerged in Edo, today''s Tokyo, in the 19th century."},{"id":"q6","question":"Tomatoes are originally from which continent?","options":[{"id":"a","text":"Europe","is_correct":false},{"id":"b","text":"The Americas","is_correct":true},{"id":"c","text":"Asia","is_correct":false},{"id":"d","text":"Africa","is_correct":false}],"explanation":"Tomatoes are native to western South America and reached Europe in the 1500s."},{"id":"q7","question":"Paella originated in which Spanish region?","options":[{"id":"a","text":"Andalusia","is_correct":false},{"id":"b","text":"Catalonia","is_correct":false},{"id":"c","text":"Galicia","is_correct":false},{"id":"d","text":"Valencia","is_correct":true}],"explanation":"Paella was first cooked by farm workers around Valencia''s Albufera lagoon."},{"id":"q8","question":"Chocolate was first consumed as a drink by civilisations in which region?","options":[{"id":"a","text":"Mesoamerica","is_correct":true},{"id":"b","text":"West Africa","is_correct":false},{"id":"c","text":"Southeast Asia","is_correct":false},{"id":"d","text":"Northern Europe","is_correct":false}],"explanation":"The Olmec, Maya and Aztec peoples drank cacao long before it reached Europe."}]'::jsonb,
  null,
  array['food and drink', 'trivia', 'origins', 'cuisine']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
