values (
  'es-trivia-origenes-gastronomia',
  'Trivia gastronómica: el origen de platos e ingredientes',
  'Pizza, café, té y chocolate: ocho preguntas sobre el origen real de platos e ingredientes famosos.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'food-drink'),
  '[{"id":"q1","question":"¿En qué país nació la pizza?","options":[{"id":"a","text":"Francia","is_correct":false},{"id":"b","text":"Italia","is_correct":true},{"id":"c","text":"Grecia","is_correct":false},{"id":"d","text":"España","is_correct":false}],"explanation":"La pizza moderna nació en Nápoles entre los siglos XVIII y XIX."},{"id":"q2","question":"El croissant se inspiró en el kipferl, un bollo de ¿qué ciudad?","options":[{"id":"a","text":"París","is_correct":false},{"id":"b","text":"Bruselas","is_correct":false},{"id":"c","text":"Viena","is_correct":true},{"id":"d","text":"Berlín","is_correct":false}],"explanation":"El kipferl vienés llegó a Francia y se convirtió en el croissant."},{"id":"q3","question":"¿Dónde se cultivó y bebió el té por primera vez?","options":[{"id":"a","text":"India","is_correct":false},{"id":"b","text":"Japón","is_correct":false},{"id":"c","text":"Sri Lanka","is_correct":false},{"id":"d","text":"China","is_correct":true}],"explanation":"La costumbre de beber té comenzó en China hace miles de años."},{"id":"q4","question":"Según la tradición, ¿en qué país africano tiene su origen el café?","options":[{"id":"a","text":"Etiopía","is_correct":true},{"id":"b","text":"Kenia","is_correct":false},{"id":"c","text":"Marruecos","is_correct":false},{"id":"d","text":"Egipto","is_correct":false}],"explanation":"La planta de café es nativa de Etiopía, donde empieza la historia de la bebida."},{"id":"q5","question":"El sushi en su forma moderna proviene de ¿qué país?","options":[{"id":"a","text":"China","is_correct":false},{"id":"b","text":"Corea","is_correct":false},{"id":"c","text":"Japón","is_correct":true},{"id":"d","text":"Tailandia","is_correct":false}],"explanation":"El sushi estilo nigiri surgió en Edo, el actual Tokio, en el siglo XIX."},{"id":"q6","question":"¿De qué continente son originarios los tomates?","options":[{"id":"a","text":"Europa","is_correct":false},{"id":"b","text":"América","is_correct":true},{"id":"c","text":"Asia","is_correct":false},{"id":"d","text":"África","is_correct":false}],"explanation":"El tomate es nativo del oeste de Sudamérica y llegó a Europa en el siglo XVI."},{"id":"q7","question":"¿En qué región de España se originó la paella?","options":[{"id":"a","text":"Andalucía","is_correct":false},{"id":"b","text":"Cataluña","is_correct":false},{"id":"c","text":"Galicia","is_correct":false},{"id":"d","text":"Valencia","is_correct":true}],"explanation":"La paella la cocinaron primero jornaleros junto a la Albufera de Valencia."},{"id":"q8","question":"El chocolate se consumió primero como bebida en civilizaciones de ¿qué región?","options":[{"id":"a","text":"Mesoamérica","is_correct":true},{"id":"b","text":"África occidental","is_correct":false},{"id":"c","text":"Sudeste asiático","is_correct":false},{"id":"d","text":"Europa del norte","is_correct":false}],"explanation":"Olmecas, mayas y aztecas bebían cacao mucho antes de que llegara a Europa."}]'::jsonb,
  null,
