insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-wildlife-records-trivia',
  'Animal Trivia: Species, Habitats and Natural Records',
  'Blue whales, cheetahs and Arctic terns: eight questions on species, habitats and natural records.',
  'trivia',
  'easy',
  'en',
  (select id from public.categories where slug = 'animals'),
  '[{"id":"q1","question":"What is the largest animal living on Earth?","options":[{"id":"a","text":"The African elephant","is_correct":false},{"id":"b","text":"The blue whale","is_correct":true},{"id":"c","text":"The giraffe","is_correct":false},{"id":"d","text":"The sperm whale","is_correct":false}],"explanation":"Blue whales can exceed 30 metres and 150 tonnes."},{"id":"q2","question":"What is the fastest land animal?","options":[{"id":"a","text":"The lion","is_correct":false},{"id":"b","text":"The pronghorn","is_correct":false},{"id":"c","text":"The cheetah","is_correct":true},{"id":"d","text":"The greyhound","is_correct":false}],"explanation":"Cheetahs can sprint at more than 100 km/h for short bursts."},{"id":"q3","question":"Which group of mammals is capable of true, sustained flight?","options":[{"id":"a","text":"Flying squirrels","is_correct":false},{"id":"b","text":"Bats","is_correct":true},{"id":"c","text":"Colugos","is_correct":false},{"id":"d","text":"Sugar gliders","is_correct":false}],"explanation":"Gliding mammals travel through the air but only bats truly fly."},{"id":"q4","question":"How many legs does a spider have?","options":[{"id":"a","text":"6","is_correct":false},{"id":"b","text":"10","is_correct":false},{"id":"c","text":"12","is_correct":false},{"id":"d","text":"8","is_correct":true}],"explanation":"Spiders are arachnids, and all arachnids have eight legs."},{"id":"q5","question":"Which living bird is the largest and cannot fly?","options":[{"id":"a","text":"The emu","is_correct":false},{"id":"b","text":"The ostrich","is_correct":true},{"id":"c","text":"The cassowary","is_correct":false},{"id":"d","text":"The emperor penguin","is_correct":false}],"explanation":"Ostriches can stand nearly three metres tall."},{"id":"q6","question":"In the wild, giant pandas live only in which country?","options":[{"id":"a","text":"Japan","is_correct":false},{"id":"b","text":"India","is_correct":false},{"id":"c","text":"Vietnam","is_correct":false},{"id":"d","text":"China","is_correct":true}],"explanation":"Wild giant pandas live in the mountain bamboo forests of China."},{"id":"q7","question":"Which bird makes the longest migration, flying between the Arctic and Antarctic?","options":[{"id":"a","text":"The Arctic tern","is_correct":true},{"id":"b","text":"The albatross","is_correct":false},{"id":"c","text":"The swallow","is_correct":false},{"id":"d","text":"The stork","is_correct":false}],"explanation":"Arctic terns can cover over 70,000 km a year."},{"id":"q8","question":"What is a group of wolves called?","options":[{"id":"a","text":"A herd","is_correct":false},{"id":"b","text":"A pack","is_correct":true},{"id":"c","text":"A flock","is_correct":false},{"id":"d","text":"A school","is_correct":false}],"explanation":"Wolves live and hunt in family groups called packs."}]'::jsonb,
