  'es',
  (select id from public.categories where slug = 'animals'),
  '[{"id":"q1","question":"¿Cuál es el animal más grande que vive en la Tierra?","options":[{"id":"a","text":"El elefante africano","is_correct":false},{"id":"b","text":"La ballena azul","is_correct":true},{"id":"c","text":"La jirafa","is_correct":false},{"id":"d","text":"El cachalote","is_correct":false}],"explanation":"Las ballenas azules pueden superar los 30 metros y las 150 toneladas."},{"id":"q2","question":"¿Cuál es el animal terrestre más rápido?","options":[{"id":"a","text":"El león","is_correct":false},{"id":"b","text":"El berrendo","is_correct":false},{"id":"c","text":"El guepardo","is_correct":true},{"id":"d","text":"El galgo","is_correct":false}],"explanation":"Los guepardos pueden esprintar a más de 100 km/h en distancias cortas."},{"id":"q3","question":"¿Qué grupo de mamíferos es capaz de un vuelo verdadero y sostenido?","options":[{"id":"a","text":"Las ardillas voladoras","is_correct":false},{"id":"b","text":"Los murciélagos","is_correct":true},{"id":"c","text":"Los colugos","is_correct":false},{"id":"d","text":"Los petauros del azúcar","is_correct":false}],"explanation":"Los mamíferos planeadores se desplazan por el aire, pero solo los murciélagos vuelan de verdad."},{"id":"q4","question":"¿Cuántas patas tiene una araña?","options":[{"id":"a","text":"6","is_correct":false},{"id":"b","text":"10","is_correct":false},{"id":"c","text":"12","is_correct":false},{"id":"d","text":"8","is_correct":true}],"explanation":"Las arañas son arácnidos, y todos los arácnidos tienen ocho patas."},{"id":"q5","question":"¿Qué ave actual es la más grande y no puede volar?","options":[{"id":"a","text":"El emú","is_correct":false},{"id":"b","text":"El avestruz","is_correct":true},{"id":"c","text":"El casuario","is_correct":false},{"id":"d","text":"El pingüino emperador","is_correct":false}],"explanation":"Los avestruces pueden medir casi tres metros de altura."},{"id":"q6","question":"En estado salvaje, los pandas gigantes viven solo en ¿qué país?","options":[{"id":"a","text":"Japón","is_correct":false},{"id":"b","text":"India","is_correct":false},{"id":"c","text":"Vietnam","is_correct":false},{"id":"d","text":"China","is_correct":true}],"explanation":"Los pandas gigantes salvajes viven en los bosques de bambú de las montañas de China."},{"id":"q7","question":"¿Qué ave realiza la migración más larga, volando entre el Ártico y la Antártida?","options":[{"id":"a","text":"El charrán ártico","is_correct":true},{"id":"b","text":"El albatros","is_correct":false},{"id":"c","text":"La golondrina","is_correct":false},{"id":"d","text":"La cigüeña","is_correct":false}],"explanation":"Los charranes árticos pueden recorrer más de 70.000 km al año."},{"id":"q8","question":"¿Cómo se llama a un grupo de lobos?","options":[{"id":"a","text":"Una manada","is_correct":true},{"id":"b","text":"Una bandada","is_correct":false},{"id":"c","text":"Una jauría","is_correct":false},{"id":"d","text":"Un enjambre","is_correct":false}],"explanation":"Los lobos viven y cazan en grupos familiares llamados manadas."}]'::jsonb,
