insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-getting-along-trivia',
  'Relationships Trivia: The Art of Getting Along',
  'Empathy, boundaries and honest talk: eight questions on the art of getting along with others.',
  'trivia',
  'easy',
  'en',
  (select id from public.categories where slug = 'relationships'),
  '[{"id":"q1","question":"Which communication style expresses your own needs clearly while respecting others?","options":[{"id":"a","text":"Passive","is_correct":false},{"id":"b","text":"Aggressive","is_correct":false},{"id":"c","text":"Assertive","is_correct":true},{"id":"d","text":"Avoidant","is_correct":false}],"explanation":"Assertiveness means stating what you need without attacking or giving in."},{"id":"q2","question":"What is the ability to understand and share another person''s feelings called?","options":[{"id":"a","text":"Empathy","is_correct":true},{"id":"b","text":"Apathy","is_correct":false},{"id":"c","text":"Indifference","is_correct":false},{"id":"d","text":"Stubbornness","is_correct":false}],"explanation":"Empathy is putting yourself in someone else''s emotional shoes."},{"id":"q3","question":"What does active listening mainly involve?","options":[{"id":"a","text":"Waiting for your turn to speak","is_correct":false},{"id":"b","text":"Paying full attention and reflecting back what you heard","is_correct":true},{"id":"c","text":"Nodding while you check your phone","is_correct":false},{"id":"d","text":"Finishing the other person''s sentences","is_correct":false}],"explanation":"Active listening means focusing on the speaker and confirming you understood."},{"id":"q4","question":"Which of these is a healthy boundary in a friendship?","options":[{"id":"a","text":"Always being available at any hour","is_correct":false},{"id":"b","text":"Agreeing with everything to avoid conflict","is_correct":false},{"id":"c","text":"Saying no when you cannot help, without guilt","is_correct":true},{"id":"d","text":"Expecting the other person to guess what you need","is_correct":false}],"explanation":"A healthy boundary lets you decline without damaging the friendship."},{"id":"q5","question":"What is a win-win outcome in a disagreement?","options":[{"id":"a","text":"Both sides lose equally","is_correct":false},{"id":"b","text":"A solution where both sides get their core needs met","is_correct":true},{"id":"c","text":"One side wins completely","is_correct":false},{"id":"d","text":"The disagreement is postponed forever","is_correct":false}],"explanation":"Win-win solutions address what matters most to each person."},{"id":"q6","question":"Which behaviour most clearly builds trust between friends?","options":[{"id":"a","text":"Sharing their secrets with others","is_correct":false},{"id":"b","text":"Always agreeing with them","is_correct":false},{"id":"c","text":"Competing with their achievements","is_correct":false},{"id":"d","text":"Keeping private what they confide in you","is_correct":true}],"explanation":"Confidentiality is one of the foundations of trust between friends."},{"id":"q7","question":"In a shared home, what does compromising mean?","options":[{"id":"a","text":"The same person always gives in","is_correct":false},{"id":"b","text":"Each side gives up something to reach an agreement","is_correct":true},{"id":"c","text":"Avoiding the issue until it goes away","is_correct":false},{"id":"d","text":"Letting the loudest person decide","is_correct":false}],"explanation":"A compromise trades concessions so both sides can accept the result."},{"id":"q8","question":"Which habit most strengthens long-term friendships?","options":[{"id":"a","text":"Never disagreeing about anything","is_correct":false},{"id":"b","text":"Talking only when you need something","is_correct":false},{"id":"c","text":"Keeping score of every favour","is_correct":false},{"id":"d","text":"Honest and regular communication","is_correct":true}],"explanation":"Friendships last when people talk openly and stay in touch."}]'::jsonb,
  null,
  array['relationships', 'trivia', 'friendship', 'communication']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-arte-de-convivir',
  'Trivia de convivencia: el arte de llevarse bien',
  'Empatía, límites y conversación honesta: ocho preguntas sobre el arte de convivir con los demás.',
  'trivia',
  'easy',
  'es',
  (select id from public.categories where slug = 'relationships'),
  '[{"id":"q1","question":"¿Qué estilo de comunicación expresa tus necesidades con claridad respetando a los demás?","options":[{"id":"a","text":"Pasivo","is_correct":false},{"id":"b","text":"Agresivo","is_correct":false},{"id":"c","text":"Asertivo","is_correct":true},{"id":"d","text":"Evitativo","is_correct":false}],"explanation":"La asertividad es decir lo que necesitas sin atacar ni ceder."},{"id":"q2","question":"¿Cómo se llama la capacidad de entender y compartir los sentimientos de otra persona?","options":[{"id":"a","text":"Empatía","is_correct":true},{"id":"b","text":"Apatía","is_correct":false},{"id":"c","text":"Indiferencia","is_correct":false},{"id":"d","text":"Terquedad","is_correct":false}],"explanation":"La empatía es ponerse en el lugar emocional del otro."},{"id":"q3","question":"¿En qué consiste principalmente la escucha activa?","options":[{"id":"a","text":"Esperar tu turno para hablar","is_correct":false},{"id":"b","text":"Prestar atención plena y confirmar lo que entendiste","is_correct":true},{"id":"c","text":"Asentir mientras miras el teléfono","is_correct":false},{"id":"d","text":"Terminar las frases de la otra persona","is_correct":false}],"explanation":"Escuchar activamente es concentrarse en quien habla y verificar que lo entendiste."},{"id":"q4","question":"¿Cuál de estas es una frontera sana en una amistad?","options":[{"id":"a","text":"Estar siempre disponible a cualquier hora","is_correct":false},{"id":"b","text":"Estar de acuerdo en todo para evitar conflictos","is_correct":false},{"id":"c","text":"Decir que no cuando no puedes ayudar, sin culpa","is_correct":true},{"id":"d","text":"Esperar que la otra persona adivine lo que necesitas","is_correct":false}],"explanation":"Un límite sano te permite negarte sin dañar la amistad."},{"id":"q5","question":"¿Qué es un resultado ganar-ganar en un desacuerdo?","options":[{"id":"a","text":"Que ambas partes pierdan por igual","is_correct":false},{"id":"b","text":"Una solución donde ambas partes cubren sus necesidades esenciales","is_correct":true},{"id":"c","text":"Que una parte gane por completo","is_correct":false},{"id":"d","text":"Postergar el desacuerdo para siempre","is_correct":false}],"explanation":"Las soluciones ganar-ganar atienden lo que más le importa a cada persona."},{"id":"q6","question":"¿Qué comportamiento genera más confianza entre amistades?","options":[{"id":"a","text":"Contar a otros sus secretos","is_correct":false},{"id":"b","text":"Estar siempre de acuerdo con ellas","is_correct":false},{"id":"c","text":"Competir con sus logros","is_correct":false},{"id":"d","text":"Guardar en privado lo que te confían","is_correct":true}],"explanation":"La confidencialidad es uno de los pilares de la confianza entre amistades."},{"id":"q7","question":"En una casa compartida, ¿qué significa llegar a un compromiso?","options":[{"id":"a","text":"Que siempre ceda la misma persona","is_correct":false},{"id":"b","text":"Que cada parte ceda algo para llegar a un acuerdo","is_correct":true},{"id":"c","text":"Evitar el tema hasta que se olvide","is_correct":false},{"id":"d","text":"Dejar que decida quien habla más fuerte","is_correct":false}],"explanation":"Un compromiso intercambia concesiones para que ambas partes acepten el resultado."},{"id":"q8","question":"¿Qué hábito fortalece más las amistades duraderas?","options":[{"id":"a","text":"No discrepar nunca sobre nada","is_correct":false},{"id":"b","text":"Hablar solo cuando necesitas algo","is_correct":false},{"id":"c","text":"Llevar la cuenta de cada favor","is_correct":false},{"id":"d","text":"La comunicación honesta y constante","is_correct":true}],"explanation":"Las amistades duran cuando las personas hablan con franqueza y se mantienen en contacto."}]'::jsonb,
  null,
  array['relaciones', 'trivia', 'amistad', 'comunicación']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

